namespace OmniCore.Client;

/// <summary>Four-language copy used only by the redesigned preferences center.</summary>
public static class PreferencesUiResources
{
    public static IReadOnlyCollection<string> Keys => _es.Keys.ToArray();
    internal static bool ContainsKey(string key) => _es.ContainsKey(key);

    internal static bool TryTranslate(string locale, string key, out string text)
    {
        var resources = locale switch { "en" => _en, "fr" => _fr, "it" => _it, _ => _es };
        return resources.TryGetValue(key, out text!);
    }

    private static Dictionary<string, string> Resource(params string[] entries)
    {
        var values = new Dictionary<string, string>(StringComparer.Ordinal);
        for (var index = 0; index < entries.Length; index += 2)
            values.Add("preferences.ui." + entries[index], entries[index + 1]);
        return values;
    }

